using System;
using System.Collections;
using System.Reflection;
using System.Globalization;

class RelogioTests {
    static Assembly app;
    static int failed;
    static object Call(string type,string method,params object[] args) {
        var found=app.GetType(type); if(found==null)throw new Exception("Componente ainda não implementado: "+type);
        return found.GetMethod(method).Invoke(null,args);
    }
    static object Field(object target,string name) {return target.GetType().GetField(name).GetValue(target);}
    static void Equal(object actual,object expected) {if(!Object.Equals(actual,expected))throw new Exception("Esperado "+expected+", recebido "+actual);}
    static void Case(string name,Action action) {try{action();Console.WriteLine("OK "+name);}catch(Exception e){failed++;Console.WriteLine("FALHOU "+name+": "+(e.InnerException??e).Message);}}
    static int Main(string[] args) {
        app=Assembly.LoadFrom(args[0]);
        Case("preferências antigas preservam hardware escolhido",()=>{
            var s=Call("ClockSettings","Parse","{\"metrics\":[\"cpu\",\"gpu\"],\"fade\":0}");
            Equal(((IList)Field(s,"Metrics")).Count,2);Equal(Field(s,"Fade"),0d);Equal(Field(s,"ShowClock"),true);
        });
        Case("preferências corrompidas não quebram abertura",()=>{var s=Call("ClockSettings","Parse","{invalid");Equal(Field(s,"Width"),300);});
        Case("ocultar todos os módulos é persistido sem inventar seleção",()=>{
            var s=Call("ClockSettings","Parse","{\"showClock\":false,\"metrics\":[],\"theme\":\"icq\"}");
            Equal(Field(s,"ShowClock"),false);Equal(((IList)Field(s,"Metrics")).Count,0);Equal(Field(s,"Theme"),"icq");
        });
        Case("tamanho e fade são limitados a faixas utilizáveis",()=>{var s=Call("ClockSettings","Parse","{\"width\":3,\"fade\":3}");Equal(Field(s,"Width"),240);Equal(Field(s,"Fade"),1d);});
        Case("salvar e reler mantém tema e módulos",()=>{
            var s=Call("ClockSettings","Parse","{\"theme\":\"winamp\",\"showClock\":false,\"metrics\":[\"ram\"]}");
            var raw=s.GetType().GetMethod("Serialize").Invoke(s,null);
            var again=Call("ClockSettings","Parse",raw);Equal(Field(again,"Theme"),"winamp");Equal(Field(again,"ShowClock"),false);Equal(((IList)Field(again,"Metrics")).Count,1);
        });
        Case("quota escolhe o bucket Codex e não mistura outra cota",()=>{
            var result=(IList)Call("QuotaParser","Read","{\"rateLimitsByLimitId\":{\"other\":{\"primary\":{\"usedPercent\":100,\"windowDurationMins\":300}},\"codex\":{\"primary\":{\"usedPercent\":23.5,\"windowDurationMins\":300},\"secondary\":{\"usedPercent\":50,\"windowDurationMins\":10080}}}}");
            Equal(result.Count,2);Equal(Field(result[0],"Used"),23.5d);Equal(Field(result[1],"Minutes"),10080d);
        });
        Case("quota ausente não vira zero",()=>{var r=(IList)Call("QuotaParser","Read","{\"rateLimits\":{\"primary\":{\"usedPercent\":null,\"windowDurationMins\":300}}}");Equal(r.Count,0);});
        Case("zero de quota é uma leitura válida",()=>{var r=(IList)Call("QuotaParser","Read","{\"rateLimits\":{\"primary\":{\"usedPercent\":0,\"windowDurationMins\":300}}}");Equal(r.Count,1);Equal(Field(r[0],"Used"),0d);});
        Case("porcentagem não depende do idioma do Windows",()=>{
            var before=CultureInfo.CurrentCulture;try{System.Threading.Thread.CurrentThread.CurrentCulture=new CultureInfo("pt-BR");
            var r=(IList)Call("QuotaParser","Read","{\"rateLimits\":{\"primary\":{\"usedPercent\":32.5,\"windowDurationMins\":300}}}");Equal(Field(r[0],"Used"),32.5d);
            }finally{System.Threading.Thread.CurrentThread.CurrentCulture=before;}
        });
        Case("CPU usa delta de tempo incluindo ocioso corretamente",()=>{Equal(Call("SensorMath","Cpu",20UL,60UL,40UL),80d);Equal(Call("SensorMath","Cpu",0UL,0UL,0UL),null);});
        Case("tema OtimizePC usa fonte IBM Plex incorporada",()=>{using(var font=(System.Drawing.Font)Call("EmbeddedFonts","Make","IBM Plex Sans",12f,System.Drawing.FontStyle.Bold))Equal(font.FontFamily.Name,"IBM Plex Sans");});
        Case("ocultar e reativar CPU mantém a ordem dos indicadores",()=>{var s=Call("ClockSettings","Parse","{\"metrics\":[\"gpu\",\"ram\",\"disk\",\"cpu\"]}");Equal(((IList)Field(s,"Metrics"))[0],"cpu");});
        Case("uso muda verde amarelo laranja vermelho sem extrapolar",()=>{
            Equal(((System.Drawing.Color)Call("WinampSkin","UsageColor",0d)).ToArgb(),System.Drawing.Color.FromArgb(0,247,0).ToArgb());
            var yellow=(System.Drawing.Color)Call("WinampSkin","UsageColor",60d);if(yellow.R<200||yellow.G<190)throw new Exception("Faixa amarela ausente");
            var orange=(System.Drawing.Color)Call("WinampSkin","UsageColor",80d);if(orange.R<230||orange.G>180)throw new Exception("Faixa laranja ausente");
            var red=(System.Drawing.Color)Call("WinampSkin","UsageColor",100d);if(red.R<230||red.G>80)throw new Exception("Faixa vermelha ausente");
            Equal(Call("WinampSkin","UsageColor",-10d),Call("WinampSkin","UsageColor",0d));Equal(Call("WinampSkin","UsageColor",120d),Call("WinampSkin","UsageColor",100d));
        });
        Case("MSN e Discord persistem sem substituir o tema por Winamp",()=>{foreach(string id in new[]{"msn","discord"}){var s=Call("ClockSettings","Parse","{\"theme\":\""+id+"\"}");Equal(Field(s,"Theme"),id);Equal(Field(Call("Theme","Get",id),"Id"),id);}});
        Case("catálogo desktop preserva os cinco temas e adiciona Napster/Kazaa",()=>{var ids=(string[])app.GetType("Theme").GetField("Ids").GetValue(null);foreach(string id in new[]{"winamp","otimizepc","icq","msn","discord","napster","kazaa"})if(Array.IndexOf(ids,id)<0)throw new Exception("Falta no catálogo: "+id);});
        Case("fontes oficiais Inter e Roboto são carregadas do executável",()=>{foreach(string name in new[]{"Inter","Roboto"})using(var f=(System.Drawing.Font)Call("EmbeddedFonts","Make",name,12f,System.Drawing.FontStyle.Regular))if(!f.FontFamily.Name.StartsWith(name))throw new Exception("Esperado "+name+", recebido "+f.FontFamily.Name);});
        Case("temas novos renderizam tamanhos extremos e módulos ocultos sem falhar",()=>{
            foreach(string id in new[]{"otimizepc","msn","discord"})foreach(int width in new[]{240,500})foreach(bool show in new[]{false,true})foreach(bool expanded in new[]{false,true}){
                var s=Call("ClockSettings","Parse","{\"theme\":\""+id+"\",\"width\":"+width+",\"showClock\":"+show.ToString().ToLowerInvariant()+",\"expanded\":"+expanded.ToString().ToLowerInvariant()+",\"metrics\":"+(show?"[\"cpu\",\"gpu\",\"ram\",\"disk\"]":"[]")+"}");
                int height=(int)Call("DesktopSkins","Height",s);if(height<100||height>750)throw new Exception("Altura inválida: "+height);
                using(var bitmap=new System.Drawing.Bitmap(width,(int)(height*width/300f)+1))using(var g=System.Drawing.Graphics.FromImage(bitmap)){
                    g.ScaleTransform(width/300f,width/300f);Call("DesktopSkins","Draw",g,s,Call("Theme","Get",id),Activator.CreateInstance(app.GetType("UsageResult")),Activator.CreateInstance(app.GetType("HardwareSample")),null,false,false,"");
                }
            }
        });
        Case("temas Napster e Kazaa mantêm escolhas de tamanho e módulos",()=>{foreach(string id in new[]{"napster","kazaa"}){var s=Call("ClockSettings","Parse","{\"theme\":\""+id+"\",\"width\":240,\"metrics\":[],\"showClock\":false}");Equal(Field(s,"Theme"),id);Equal(Field(s,"Width"),240);Equal(((IList)Field(s,"Metrics")).Count,0);Equal(Field(s,"ShowClock"),false);Equal(Field(Call("Theme","Get",id),"Id"),id);}});
        Case("bibliotecas clássicas renderizam vazias e com sensores nos tamanhos extremos",()=>{foreach(string id in new[]{"napster","kazaa"})foreach(int width in new[]{240,500})foreach(bool shown in new[]{false,true})foreach(bool expanded in new[]{false,true}){
            var s=Call("ClockSettings","Parse","{\"theme\":\""+id+"\",\"font\":\"sans\",\"width\":"+width+",\"showClock\":"+shown.ToString().ToLowerInvariant()+",\"expanded\":"+expanded.ToString().ToLowerInvariant()+",\"metrics\":"+(shown?"[\"cpu\",\"gpu\",\"ram\",\"disk\"]":"[]")+"}");
            int height=(int)Call("RetroSkins","Height",s);if(height<100||height>750)throw new Exception("Altura inadequada");using(var b=new System.Drawing.Bitmap(width,(int)(height*width/300f)+1))using(var g=System.Drawing.Graphics.FromImage(b)){g.ScaleTransform(width/300f,width/300f);Call("RetroSkins","Draw",g,s,Call("Theme","Get",id),Activator.CreateInstance(app.GetType("UsageResult")),Activator.CreateInstance(app.GetType("HardwareSample")),null,false,false,"");}
        }});
        Case("Aero persiste e tem janela com cantos arredondados",()=>{var s=Call("ClockSettings","Parse","{\"theme\":\"aero\"}");Equal(Field(s,"Theme"),"aero");Equal(Field(Call("Theme","Get","aero"),"Id"),"aero");using(var r=(System.Drawing.Region)Call("AeroSkin","WindowRegion",300,400)){Equal(r.IsVisible(0,0),false);Equal(r.IsVisible(150,200),true);}});
        Case("Aero renderiza fundo incorporado e aceita foto/fade nos modos e tamanhos",()=>{foreach(int width in new[]{240,500})foreach(bool shown in new[]{false,true})foreach(bool photo in new[]{false,true}){
            var s=Call("ClockSettings","Parse","{\"theme\":\"aero\",\"font\":\"sans\",\"fade\":0.3,\"width\":"+width+",\"showClock\":"+shown.ToString().ToLowerInvariant()+",\"expanded\":"+shown.ToString().ToLowerInvariant()+",\"metrics\":"+(shown?"[\"cpu\",\"gpu\",\"ram\",\"disk\"]":"[]")+"}");
            int height=(int)Call("AeroSkin","Height",s);using(var b=new System.Drawing.Bitmap(width,(int)(height*width/300f)+1))using(var g=System.Drawing.Graphics.FromImage(b)){g.ScaleTransform(width/300f,width/300f);Call("AeroSkin","Draw",g,s,Call("Theme","Get","aero"),Activator.CreateInstance(app.GetType("UsageResult")),Activator.CreateInstance(app.GetType("HardwareSample")),null,photo,false,"");}
        }});
        Case("Aero mantém corpo de texto de pelo menos 12 pixels na janela estreita",()=>{foreach(int width in new[]{240,320,500})foreach(float requested in new[]{8f,10f,12f}){float physical=(float)Call("AeroSkin","TextSize",requested,width)*width/300f;if(physical<11.99f)throw new Exception("Texto pequeno: "+physical);}});
        Case("Windows XP persiste e preserva selecao dos modulos",()=>{var s=Call("ClockSettings","Parse","{\"theme\":\"xp\",\"metrics\":[],\"showClock\":false}");Equal(Field(s,"Theme"),"xp");Equal(Field(Call("Theme","Get","xp"),"Name"),"AZUL CLÁSSICO");Equal(((IList)Field(s,"Metrics")).Count,0);Equal(Field(s,"ShowClock"),false);});
        Case("Windows XP renderiza cotas e todos os modos nos tamanhos extremos",()=>{foreach(int width in new[]{240,300,500})foreach(bool shown in new[]{false,true})foreach(bool expanded in new[]{false,true})foreach(bool photo in new[]{false,true}){
            var s=Call("ClockSettings","Parse","{\"theme\":\"xp\",\"font\":\"sans\",\"width\":"+width+",\"showClock\":"+shown.ToString().ToLowerInvariant()+",\"expanded\":"+expanded.ToString().ToLowerInvariant()+",\"metrics\":"+(shown?"[\"cpu\",\"gpu\",\"ram\",\"disk\"]":"[]")+"}");
            var usage=Activator.CreateInstance(app.GetType("UsageResult"));var quotas=(IList)Field(usage,"Windows");foreach(double used in new[]{0d,100d}){var q=Activator.CreateInstance(app.GetType("Quota"));app.GetType("Quota").GetField("Used").SetValue(q,used);app.GetType("Quota").GetField("Minutes").SetValue(q,300d);quotas.Add(q);}
            int height=(int)Call("XpSkin","Height",s);if(height*width/300f>900)throw new Exception("Altura excede limite da janela");using(var b=new System.Drawing.Bitmap(width,(int)(height*width/300f)+1))using(var g=System.Drawing.Graphics.FromImage(b)){g.Clear(System.Drawing.Color.Magenta);g.ScaleTransform(width/300f,width/300f);Call("XpSkin","Draw",g,s,Call("Theme","Get","xp"),usage,Activator.CreateInstance(app.GetType("HardwareSample")),null,photo,false,"Falha simulada");}
        }});
        Case("musica persiste ocultacao sem alterar sensores",()=>{var s=Call("ClockSettings","Parse","{\"showMusic\":false,\"metrics\":[\"ram\"]}");Equal(Field(s,"ShowMusic"),false);Equal(((IList)Field(s,"Metrics")).Count,1);var copy=Call("ClockSettings","Parse",s.GetType().GetMethod("Serialize").Invoke(s,null));Equal(Field(copy,"ShowMusic"),false);});
        Case("Spotify seleciona apenas a sessao correta sem controlar outros players",()=>{Equal(Call("SpotifyMedia","IsSpotify","Spotify.exe"),true);Equal(Call("SpotifyMedia","IsSpotify","SpotifyAB.SpotifyMusic_zpdnekdrzrea0!Spotify"),true);foreach(string id in new[]{"chrome.exe","vlc.exe","not-spotify.exe","",null})Equal(Call("SpotifyMedia","IsSpotify",id),false);});
        Case("player renderiza todos os temas, faixa longa e estado vazio sem extrapolar",()=>{var ids=(string[])app.GetType("Theme").GetField("Ids").GetValue(null);foreach(string id in ids)foreach(int width in new[]{240,500})foreach(bool available in new[]{true,false}){var s=Call("ClockSettings","Parse","{\"theme\":\""+id+"\",\"width\":"+width+"}");var music=Activator.CreateInstance(app.GetType("MusicState"));music.GetType().GetField("Available").SetValue(music,available);music.GetType().GetField("Title").SetValue(music,new string('A',200));using(var b=new System.Drawing.Bitmap(width,170))using(var g=System.Drawing.Graphics.FromImage(b)){g.ScaleTransform(width/300f,width/300f);Call("MusicPanel","Draw",g,s,Call("Theme","Get",id),music,0);foreach(string action in new[]{"previous","toggle","next"})using(var icon=(System.Drawing.Bitmap)Call("MusicPanel","ButtonImage",action,Call("Theme","Get",id),true)){if(icon.Width<20)throw new Exception("Botao pequeno");}}}});
        Case("GPU agrupa motores fisicos sem somar motores distintos",()=>{Equal(Call("GpuReader","EngineKey","pid_10_luid_0x0_0x1_phys_0_eng_0_engtype_3D"),Call("GpuReader","EngineKey","pid_20_luid_0x0_0x1_phys_0_eng_0_engtype_3D"));if(Object.Equals(Call("GpuReader","EngineKey","pid_10_luid_0x0_0x1_phys_0_eng_0_engtype_3D"),Call("GpuReader","EngineKey","pid_10_luid_0x0_0x1_phys_0_eng_1_engtype_Copy")))throw new Exception("Motores misturados");});
        Case("Claude reconhece cotas reais e nao transforma ausencia em zero",()=>{var value=Call("ClaudeClient","Parse","{\"five_hour\":{\"utilization\":0,\"resets_at\":\"2026-10-26T12:00:00Z\"},\"seven_day\":{\"utilization\":82.5}}");Equal(Field(value,"Provider"),"Claude");var windows=(IList)Field(value,"Windows");Equal(windows.Count,2);Equal(Field(windows[0],"Used"),0d);Equal(Field(windows[1],"Used"),82.5d);var missing=Call("ClaudeClient","Parse","{\"five_hour\":{\"utilization\":null}}");Equal(((IList)Field(missing,"Windows")).Count,0);Equal(Field(missing,"At"),null);});
        Case("janela restaura monitor secundario, coordenada negativa e monitor removido",()=>{var screens=new[]{new System.Drawing.Rectangle(0,0,1920,1032),new System.Drawing.Rectangle(1920,0,1366,720)};Equal(Call("WindowPlacement","Fit",new System.Drawing.Rectangle(3100,650,300,500),screens),new System.Drawing.Point(2986,220));Equal(Call("WindowPlacement","Fit",new System.Drawing.Rectangle(-1200,10,300,400),new[]{new System.Drawing.Rectangle(-1366,0,1366,720)}),new System.Drawing.Point(-1200,10));Equal(Call("WindowPlacement","Fit",new System.Drawing.Rectangle(4000,100,300,500),screens),new System.Drawing.Point(1620,100));});
        Case("alerta soa uma vez ao cruzar limite e respeita renovacao",()=>{var policy=Activator.CreateInstance(app.GetType("QuotaAlertPolicy"));var method=policy.GetType().GetMethod("Observe");var now=DateTime.UtcNow;Equal(method.Invoke(policy,new object[]{"codex",300d,(long?)100,89d,10,now}),false);Equal(method.Invoke(policy,new object[]{"codex",300d,(long?)100,90d,10,now}),true);Equal(method.Invoke(policy,new object[]{"codex",300d,(long?)100,95d,10,now.AddMinutes(20)}),false);Equal(method.Invoke(policy,new object[]{"codex",300d,(long?)200,5d,10,now.AddHours(5)}),false);Equal(method.Invoke(policy,new object[]{"codex",300d,(long?)200,91d,10,now.AddHours(7)}),true);});
        Case("sons desligados por padrao e configuracao invalida nao executa audio",()=>{var s=Call("ClockSettings","Parse","{\"alertsEnabled\":true,\"alertRemaining\":99,\"alertSound\":\"data:audio/wav;base64,AAAA\"}");Equal(Field(s,"AlertRemaining"),50);Equal(Field(s,"AlertSound"),"");var original=Call("ClockSettings","Parse","{}");Equal(Field(original,"AlertsEnabled"),false);});
        Case("WAV PCM valido sobrevive a exportacao e rejeita audio truncado",()=>{byte[] wave=new byte[60];Action<int,string> text=(offset,value)=>System.Text.Encoding.ASCII.GetBytes(value).CopyTo(wave,offset);text(0,"RIFF");BitConverter.GetBytes(52).CopyTo(wave,4);text(8,"WAVE");text(12,"fmt ");BitConverter.GetBytes(16).CopyTo(wave,16);BitConverter.GetBytes((ushort)1).CopyTo(wave,20);BitConverter.GetBytes((ushort)1).CopyTo(wave,22);BitConverter.GetBytes(8000).CopyTo(wave,24);BitConverter.GetBytes(8000).CopyTo(wave,28);BitConverter.GetBytes((ushort)1).CopyTo(wave,32);BitConverter.GetBytes((ushort)8).CopyTo(wave,34);text(36,"data");BitConverter.GetBytes(16).CopyTo(wave,40);Equal(Call("SoundAlerts","ValidWave",wave),true);string data="data:audio/wav;base64,"+Convert.ToBase64String(wave);Equal(Call("SoundAlerts","Clean",data),data);BitConverter.GetBytes(5000).CopyTo(wave,40);Equal(Call("SoundAlerts","ValidWave",wave),false);});
        Case("temas com player cabem na tela secundaria sem perder botoes",()=>{foreach(string id in (string[])app.GetType("Theme").GetField("Ids").GetValue(null)){var s=Call("ClockSettings","Parse","{\"theme\":\""+id+"\",\"width\":500,\"expanded\":true,\"metrics\":[\"cpu\",\"gpu\",\"ram\",\"disk\"]}");int width=(int)Call("WindowPlacement","WidthToFit",s,720);Equal(Field(s,"Width"),500);s.GetType().GetField("Width").SetValue(s,width);double height=((int)Call("WindowPlacement","ClockHeight",s)+(int)Call("MusicPanel","Height",s))*width/300d;if(height>720.01)throw new Exception("Tema nao cabe: "+id);}});
        Case("volume e limitado e identifica somente processos Spotify",()=>{Equal(Call("SpotifyVolume","Clamp",-50),0);Equal(Call("SpotifyVolume","Clamp",170),100);Equal(Call("SpotifyVolume","Clamp",63),63);Equal(Call("SpotifyVolume","IsSpotifyProcess","Spotify"),true);foreach(string name in new[]{"chrome","vlc","notSpotify",null})Equal(Call("SpotifyVolume","IsSpotifyProcess",name),false);});
        Case("repeticao percorre desligado fila faixa sem inventar estado",()=>{Equal(Call("SpotifyMedia","NextRepeat",0),2);Equal(Call("SpotifyMedia","NextRepeat",2),1);Equal(Call("SpotifyMedia","NextRepeat",1),0);});
        Case("volume shuffle repetir e mute renderizam em todos os temas",()=>{foreach(string id in (string[])app.GetType("Theme").GetField("Ids").GetValue(null))foreach(bool active in new[]{false,true}){foreach(string action in new[]{"shuffle","repeat","repeat-one","volume-down","volume-up","mute"})using(var b=(System.Drawing.Bitmap)Call("MusicPanel","ButtonImage",action,Call("Theme","Get",id),active)){if(b.Width<20||b.Height<18)throw new Exception("Controle pequeno");}foreach(object value in new object[]{null,0,100})using(var b=new System.Drawing.Bitmap(158,22))using(var g=System.Drawing.Graphics.FromImage(b))Call("MusicPanel","VolumeTrack",g,Call("Theme","Get",id),value);}});
        Case("publicacao nao incorpora sprites ou logos dos programas de referencia",()=>{foreach(string name in app.GetManifestResourceNames())if(name.StartsWith("Classic")||name.StartsWith("Xp")||name=="NapsterReference"||name=="KazaaReference")throw new Exception("Recurso legado: "+name);});
        Case("catalogo da publicacao usa os nove nomes aprovados",()=>{string[] ids={"winamp","otimizepc","icq","msn","discord","napster","kazaa","aero","xp"};string[] names={"METAL","OTIMIZEPC","JARDIM","CONEXÃO","COMUNIDADE","FREQUÊNCIA","LIMA","BRISA","AZUL CLÁSSICO"};for(int i=0;i<ids.Length;i++)Equal(Field(Call("Theme","Get",ids[i]),"Name"),names[i]);});
        Case("trilha de volume metal nao apaga botoes vizinhos",()=>{using(var b=new System.Drawing.Bitmap(300,22))using(var g=System.Drawing.Graphics.FromImage(b)){g.Clear(System.Drawing.Color.Magenta);Call("WinampSkin","DrawVolumeTrack",g,(int?)72);Equal(b.GetPixel(200,10).ToArgb(),System.Drawing.Color.Magenta.ToArgb());}});
        Console.WriteLine("Falhas: "+failed);return failed==0?0:1;
    }
